{"command": "cd /workspace && cat > /workspace/kg.py <<'EOF'
"""Helpers for building the keygen tune on this FT2 clone.

Verified engine facts (measured, not assumed):
  * note->period uses the Amiga table; C-4 prints 172.27 Hz with a P=256 loop, and every
    higher octave doubles it.  Samples therefore sound as written only when their single
    cycle is one period long at the target pitch.
"""
import numpy as np, wave, json, subprocess

SR = 44100
STEPS = 16

def write_sc(path, y, sr=SR):
    y = np.asarray(y, float)
    y = y / np.abs(y).max()
    x = (y * 0.98 * 32767).astype(np.int16)
    w = wave.open(path, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr)
    w.writeframes(x.tobytes()); w.close()
    return len(x)

def saw_cycle(P, nharm=None, decay=1.0, phases=0.0):
    """Band-limited-ish saw built from k harmonics with 1/k**decay amplitudes."""
    nharm = nharm or P // 2
    y = np.zeros(P)
    for k in range(1, nharm + 1):
        y += np.sin(2 * np.pi * k * np.arange(P) / P + phases * k) / (k ** decay)
    return y

def sqr_cycle(P, nharm=None, duty=0.5):
    nharm = nharm or P // 2
    y = np.zeros(P)
    ph = 2 * np.pi * np.arange(P) / P
    for k in range(1, nharm + 1, 2):
        y += np.sin(k * ph) / k
    return y

def notes(name):
    return name

def semis_to_freq(s, base=86.3296):
    return base * 2 ** (s / 12.0)

NOTE_NAMES = ['C-', 'C#', 'D-', 'D#', 'E-', 'F-', 'F#', 'G-', 'G#', 'A-', 'A#', 'B-']

def nn(midi):
    """midi number (60 = C-4 in FT2 terms) -> FT2 note name"""
    return NOTE_NAMES[midi % 12] + str(midi // 12 - 1)

def midi(name):
    pc = NOTE_NAMES.index(name[:2] if name[1] == '#' else name[0] + '-')
    return pc + 12 * (int(name[-1]) + 1)
