import numpy as np

def cycle(L, amps, phase=0.35):
    """Band-limited single cycle of exactly L samples from harmonic amps dict/list."""
    n = np.arange(L)
    y = np.zeros(L)
    if isinstance(amps, dict):
        items = amps.items()
    else:
        items = enumerate(amps, start=1)
    for k, a in items:
        if a == 0: continue
        if k > L/2: continue
        y += a * np.sin(2*np.pi*k*n/L + phase*k)
    return y

def saw(L, nh=None, tilt=1.0, phase=0.35):
    nh = nh or int(L/2)
    return cycle(L, [(1.0/k**tilt) for k in range(1, nh+1)], phase)

def square(L, nh=None, tilt=1.0, phase=0.35):
    nh = nh or int(L/2)
    return cycle(L, [(1.0/k**tilt) if k%2 else 0.0 for k in range(1, nh+1)], phase)

def pulse(L, duty=0.15, nh=None, tilt=0.8, phase=0.0):
    """Narrow pulse via Fourier of asymmetric rectangle."""
    nh = nh or int(L/2)
    a = []
    import math
    for k in range(1, nh+1):
        a.append((2.0/(k*math.pi))*abs(math.sin(math.pi*k*duty))/ (k**tilt))
    return cycle(L, a, phase)

def tri(L, nh=None, tilt=2.0):
    nh = nh or int(L/2)
    a=[]
    for k in range(1, nh+1):
        if k%2==0: a.append(0.0)
        else: a.append(((-1)**((k-1)//2))/ (k**tilt))
    return cycle(L, a, 0.0)

def fm(L, ratio=2.0, index=2.0, harmonics=None):
    """Simple FM (Chowning) single cycle."""
    n = np.arange(L)
    return np.sin(2*np.pi*n/L + index*np.sin(2*np.pi*ratio*n/L))
