"""Verified engine model for ft2-clone (single-cycle / internal-period samples)."""
import numpy as np
SR = 44100
NM = ['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']

def nn(s): return NM[s % 12] + str(s // 12 - 1)
def sn(name):
    pc = NM.index(name[0] + ('-' if name[1] != '#' else '#'))
    return pc + 12 * (int(name[-1]) + 1)

def note_freq(note, cycle_len):
    """VERIFIED: f = SR/cycle_len * 2^((note-60)/12).  Accurate to <5 cents."""
    return SR / cycle_len * 2 ** ((note - 60) / 12.0)

def cycle_for(note, freq):
    return SR / (freq * 2 ** (-(note - 60) / 12.0))

# Concert-pitch reference: cycle length that puts A-4 (note 69) at 440 Hz.
CYC_A4 = SR / (440.0 * 2 ** (-(69 - 60) / 12.0))   # ~168.0

def rows_per_sec(bpm, speed):
    """VERIFIED: rows/sec = bpm*0.4/speed."""
    return bpm * 0.4 / speed
