                pats[p][(r+3, CH['ORGAN'])] = dict(note=None,inst=None,vol=None,e=12,ep=0)

        # ---------- BELL: accent on downbeats of A/B sections ----------
        if phrase in (1,2,3):
            put(p,'BELL', 0, ch_notes[3] + 24, 40)

    return pats

if __name__=='__main__':
    pats = build()
    for pi in (0,1,8,16,24):
