"""Warm single-cycle instrument waveforms.

Cycle lengths here are short (84..169 samples), so the fundamental already sits
high in the spectrum; we deliberately roll harmonics off HARD (and low-pass the
result) so the tone has body rather than hiss.
"""
import numpy as np

def _cyc(L, harm, phase=0.35):
    n = np.arange(L); y = np.zeros(L)
    for k, a in enumerate(harm, start=1):
        if a == 0 or k > L/2: continue
        y += a*np.sin(2*np.pi*k*n/L + phase*k)
    return y

def _soft(y, cutoff):
    """Gentle FFT low-pass, cutoff = fraction of Nyquist."""
    L=len(y)
    F=np.fft.rfft(y); fr=np.fft.rfftfreq(L)
    F *= np.exp(-(fr/max(cutoff,1e-6))**2)
    y=np.fft.irfft(F,L)
    return y - y.mean()

def lead(L=113, cut=0.30):
    h=[(1.0/k**1.5) if k%2 else (0.22/k**1.5) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.4), cut)

def pluck(L=126, cut=0.26):
    h=[(1.0/k**1.4) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.6), cut)

def arp(L=100, cut=0.18):
    h=[(1.0/k**1.7)*(0.7+0.3*(-1)**k) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.5), cut)

def bell(L=84, cut=0.22):
    n=np.arange(L); y=np.zeros(L)
    for r,a in zip((1,2,3,4),(1.0,0.35,0.18,0.08)):
        y+=a*np.sin(2*np.pi*r*n/L+0.3)
    return _soft(y, cut)

def pad(L=169, cut=0.16):
    h=[(1.0/k**1.9) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.8), cut)

def bass(L=169, cut=0.13):
    h=[(1.0/k**1.3)*np.exp(-k/9.0) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.2), cut)

def sub(L=169, cut=0.08):
    h=[(1.0/k**2.2)*np.exp(-k/6.0) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.0), cut)

def organ(L=168, cut=0.15):
    amps={1:1.0,2:0.55,3:0.40,4:0.25,5:0.16,6:0.11,8:0.07}
    h=[amps.get(k,0.0) for k in range(1,int(L/2)+1)]
    return _soft(_cyc(L,h,0.25), cut)
